const token = $env.GITHUB_TOKEN;
const repos = ($env.AIFLOW_REPOS || '').split(',').map(s => s.trim()).filter(Boolean);
const api = 'https://api.github.com';

async function gh(method, path, body) {
  return this.helpers.httpRequest({
    method,
    url: api + path,
    headers: {
      Authorization: 'Bearer ' + token,
      Accept: 'application/vnd.github+json',
      'User-Agent': 'aiflow'
    },
    body,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
}

const out = [];

for (const repo of repos) {
  const def = await gh.call(this, 'GET', `/repos/${repo}`);
  if (def.statusCode !== 200) continue;
  const base = def.body.default_branch;

  const br = await gh.call(this, 'GET', `/repos/${repo}/branches?per_page=100`);
  if (br.statusCode !== 200) continue;

  for (const b of br.body) {
    if (b.name === base) continue;

    const design = await gh.call(this, 'GET',
      `/repos/${repo}/contents/.aiflow/02-design.md?ref=${encodeURIComponent(b.name)}`);
    if (design.statusCode !== 200) continue;

    const owner = repo.split('/')[0];
    const existing = await gh.call(this, 'GET',
      `/repos/${repo}/pulls?state=open&head=${owner}:${encodeURIComponent(b.name)}`);
    if (existing.statusCode !== 200) continue;
    if (existing.body.length > 0) continue;

    const title = Buffer.from(design.body.content, 'base64')
      .toString('utf8')
      .split('\n')
      .find(l => /^#+\s/.test(l))
      ?.replace(/^#+\s*/, '')
      ?.slice(0, 70) || b.name;

    const created = await gh.call(this, 'POST', `/repos/${repo}/pulls`, {
      title,
      head: b.name,
      base,
      body: 'Design is in `.aiflow/02-design.md`. Labelled `ai-build`, so plan and build start now.'
    });
    if (created.statusCode !== 201) continue;

    const num = created.body.number;
    await gh.call(this, 'POST', `/repos/${repo}/issues/${num}/labels`, { labels: ['ai-build'] });

    const short = repo.split('/')[1];
    out.push({ json: {
      text: '\u{1F680} <b>' + short + '</b> design picked up\n#' + num + ' ' + title + '\n' + created.body.html_url
    }});
  }
}

return out;
